// MIT. Freeze original payment adjustments beside the accountant's gross rows.
import {createHash} from 'node:crypto';
import {isDeepStrictEqual} from 'node:util';
import {ADJUSTMENT_EXPORT_SCHEMA,compileAdjustmentExport} from '../adjustments.mjs';

const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const copy=value=>structuredClone(value);
const need=(ok,message)=>{if(!ok)throw Object.assign(new Error(message),{code:'ACCOUNTANT_ADJUSTMENTS_CHANGED',status:409});};
const AMOUNTS=Object.freeze(['grossAmountAtomic','refundedAmountAtomic','pendingRefundAmountAtomic',
  'remainingAmountAtomic','availableRefundAmountAtomic','cancelledAmountAtomic','overRefundedAmountAtomic']);
export const ADJUSTMENT_COLUMNS=Object.freeze(['sourceAdjustmentsSha256',...AMOUNTS,
  'refundStatus','adjustmentCount','latestRefundTransferAt','latestCancellationEffectiveAt']);
const latest=values=>values.filter(value=>typeof value==='string'&&Number.isFinite(Date.parse(value)))
  .sort((a,b)=>Date.parse(b)-Date.parse(a))[0]??null;

/** Validate one frozen snapshot against the exact retained original report. */
export function freezeAccountantAdjustments({adjustmentsBytes,report,source,periodCloseDocument}={}){
  if(adjustmentsBytes===undefined||adjustmentsBytes===null){
    need(!source.adjustmentsSha256&&!periodCloseDocument?.adjustmentsSha256,'The selected adjustment snapshot must accompany this handoff.');
    return null;
  }
  need(Buffer.isBuffer(adjustmentsBytes)||adjustmentsBytes instanceof Uint8Array,'Retain the original adjustment bytes.');
  const raw=Buffer.from(adjustmentsBytes);
  need(raw.length>0&&raw.length<=128_000_000,'The selected adjustment snapshot exceeds the original report size limit.');
  const digest=hash(raw);let snapshot;
  try{snapshot=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw));}
  catch{need(false,'The original adjustment snapshot must be complete UTF-8 JSON.');}
  need(snapshot?.schema===ADJUSTMENT_EXPORT_SCHEMA&&Array.isArray(snapshot.events)&&
    Number.isSafeInteger(snapshot.workspaceRevision)&&snapshot.workspaceRevision>=0&&
    typeof snapshot.exportedAt==='string'&&Number.isFinite(Date.parse(snapshot.exportedAt)),
    'Choose a completed original adjustment export.');
  need(source.adjustmentsSha256===digest,'The selected adjustment bytes changed before this handoff.');
  for(const key of ['runId','reportSha256','manifestSha256','inputManifestSha256'])
    need(snapshot.source?.[key]===source[key],'The adjustment snapshot belongs to another original reconciliation.');
  if(periodCloseDocument)need(periodCloseDocument.adjustmentsSha256===digest,
    'Use the adjustment snapshot frozen by this original period close.');
  need(isDeepStrictEqual(snapshot.originalReport,report)&&snapshot.events.length===report.ledger.length,
    'The adjustment snapshot must retain every exact original gross event.');
  const records=snapshot.events.flatMap(item=>{need(Array.isArray(item?.adjustments),'Retain each event adjustment history.');return item.adjustments;});
  const rebuilt=compileAdjustmentExport({report,source:snapshot.source,records,
    workspaceRevision:snapshot.workspaceRevision,exportedAt:snapshot.exportedAt});
  need(isDeepStrictEqual(rebuilt.events,snapshot.events)&&isDeepStrictEqual(rebuilt.period,snapshot.period)&&
    isDeepStrictEqual(rebuilt.dateBasis,snapshot.dateBasis),'The retained adjustment totals or native payment histories changed.');
  const rows=new Map(),groups=new Map();let refundedRows=0,cancelledRows=0,adjustedRows=0;
  for(const item of rebuilt.events){
    const original=item.original,totals=copy(item.totals);
    need(!rows.has(original.eventId),'A retained adjustment event is repeated.');
    const dates={latestRefundTransferAt:latest(item.adjustments.filter(record=>record.kind==='REFUND'&&record.status==='VERIFIED')
      .map(record=>record.verification?.transferAt)),
      latestCancellationEffectiveAt:latest(item.adjustments.filter(record=>record.kind==='CANCELLATION'&&record.status==='RECORDED')
        .map(record=>record.effectiveAt))};
    rows.set(original.eventId,{...totals,...dates});
    if(BigInt(totals.refundedAmountAtomic)>0n)refundedRows++;
    if(BigInt(totals.cancelledAmountAtomic)>0n)cancelledRows++;
    if(totals.adjustmentCount)adjustedRows++;
    const key=original.network+'\n'+original.assetDigest;
    let group=groups.get(key);
    if(!group){group={network:original.network,assetDigest:original.assetDigest,eventCount:0,
      ...Object.fromEntries(AMOUNTS.map(field=>[field,0n]))};groups.set(key,group);}
    group.eventCount++;for(const field of AMOUNTS)group[field]+=BigInt(totals[field]);
  }
  return {source:{schema:snapshot.schema,sha256:digest,bytes:raw.length,workspaceRevision:snapshot.workspaceRevision,
    exportedAt:snapshot.exportedAt,dateBasis:copy(snapshot.dateBasis)},rows,
    summary:{adjustedRows,refundedRows,cancelledRows,adjustmentCount:records.length,
      groups:[...groups.values()].map(group=>({...group,...Object.fromEntries(AMOUNTS.map(field=>[field,String(group[field])]))}))}};
}

export function validateAccountantAdjustmentRow(row){
  const totals=row.adjustments;
  need(totals&&totals.grossAmountAtomic===row.original.amountAtomic,'The adjustment row must preserve its original gross amount.');
  for(const field of AMOUNTS)need(typeof totals[field]==='string'&&/^-?(?:0|[1-9][0-9]*)$/.test(totals[field])&&
    (field==='remainingAmountAtomic'||BigInt(totals[field])>=0n),'Retain exact atomic adjustment amounts.');
  const gross=BigInt(totals.grossAmountAtomic),returned=BigInt(totals.refundedAmountAtomic),remaining=gross-returned;
  need(remaining===BigInt(totals.remainingAmountAtomic)&&
    BigInt(totals.overRefundedAmountAtomic)===(remaining<0n?-remaining:0n)&&
    BigInt(totals.availableRefundAmountAtomic)===(remaining-BigInt(totals.pendingRefundAmountAtomic)>0n?
      remaining-BigInt(totals.pendingRefundAmountAtomic):0n)&&
    totals.refundStatus===(returned===0n?'NONE':returned<gross?'PARTIAL':returned===gross?'FULL':'OVER_RETURNED')&&
    Number.isSafeInteger(totals.adjustmentCount)&&totals.adjustmentCount>=0,
    'The retained return, remaining or refund status changed.');
  return totals;
}

// MIT. Small native Bitwave Data Fusion transport. No automatic write retry.
import {bitwaveCheck,bitwaveTargetId} from './bitwave.mjs';

export const BITWAVE_API_BASE='https://api4.bitwave.io';
export const BITWAVE_TOKEN_ENV='BITWAVE_ACCESS_TOKEN';
export class BitwaveHttpClient{
  constructor({fetchImpl=globalThis.fetch,token=()=>process.env[BITWAVE_TOKEN_ENV],intervalMs=700,timeoutMs=20000}={}){
    this.fetch=fetchImpl;this.token=token;this.intervalMs=intervalMs;this.timeoutMs=timeoutMs;this.lastRequestAt=0;this.controllers=new Set();
  }
  available(){const token=this.token();return typeof token==='string'&&token.length>0;}
  async request({orgId,dataSourceId,kind,body,pageToken}){
    bitwaveTargetId(orgId,'organization ID');if(dataSourceId!==undefined)bitwaveTargetId(dataSourceId);
    bitwaveCheck(['create','add','rows'].includes(kind),'INVALID_BITWAVE_REQUEST','Choose an original Data Fusion operation.');
    bitwaveCheck(kind==='create'||dataSourceId,'BITWAVE_SOURCE_REQUIRED','Bind a native data source first.');
    const token=this.token();bitwaveCheck(typeof token==='string'&&token.length>0&&!/[\r\n]/.test(token),'BITWAVE_TOKEN_REQUIRED','Configure BITWAVE_ACCESS_TOKEN in this merchant host, then retry the selected operation.');
    const root=BITWAVE_API_BASE+'/v3/orgs/'+encodeURIComponent(orgId)+'/data-sources';
    const url=new URL(kind==='create'?root:root+'/'+encodeURIComponent(dataSourceId)+(kind==='add'?'/add-rows':'/table-rows'));
    if(kind==='rows'){url.searchParams.set('pageSize','250');if(pageToken)url.searchParams.set('pageToken',pageToken);}
    const delay=this.lastRequestAt+this.intervalMs-Date.now();if(delay>0)await new Promise(resolve=>setTimeout(resolve,delay));
    this.lastRequestAt=Date.now();const controller=new AbortController();this.controllers.add(controller);
    const timer=setTimeout(()=>controller.abort(new Error('Bitwave response deadline exceeded.')),this.timeoutMs);
    try{
      const response=await this.fetch(url,{method:kind==='rows'?'GET':'POST',headers:{Authorization:'Bearer '+token,Accept:'application/json',...(kind==='rows'?{}:{'Content-Type':'application/json'})},
        body:kind==='rows'?undefined:body,redirect:'error',signal:controller.signal});
      let size=0;const chunks=[];
      for await(const chunk of response.body??[]){size+=chunk.length;bitwaveCheck(size<=64*1024*1024,'BITWAVE_RESPONSE_LIMIT','The native response exceeds 64 MiB.');chunks.push(Buffer.from(chunk));}
      const bytes=Buffer.concat(chunks);let value=null;
      try{value=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}catch{}
      const headers={};for(const key of ['content-type','date','retry-after','x-request-id','x-trace-id']){const value=response.headers.get(key);if(value!==null)headers[key]=value;}
      return {status:response.status,headers,bytes,value,receivedAt:new Date().toISOString(),url:url.toString()};
    }finally{clearTimeout(timer);this.controllers.delete(controller);}
  }
  abort(){for(const controller of this.controllers)controller.abort(new Error('Merchant workspace is closing.'));}
}

// MIT. Bitwave Data Fusion representation of the original accountant handoff.
// All financial/source values remain exact strings. The accountant engine owns returns.
import {createHash,randomUUID} from 'node:crypto';
import {CSV_COLUMNS,EDITABLE_COLUMNS,accountantColumns,inspectHandoff,validateHandoff,validateRevision} from './engine.mjs';

export const BITWAVE_PLAN_SCHEMA='stellar-forge.bitwave-data-source.v1';
export const BITWAVE_CAPTURE_SCHEMA='stellar-forge.bitwave-data-source-capture.v1';
const EXPORT_COLUMNS=Object.freeze(['accountantExportRowId','accountantExportId','accountantRevisionId','accountantRevisionSha256']);
export const BITWAVE_COLUMNS=Object.freeze([...EXPORT_COLUMNS,...CSV_COLUMNS]);
export const BITWAVE_SOURCE_COLUMNS=Object.freeze(BITWAVE_COLUMNS.filter(name=>!EDITABLE_COLUMNS.includes(name)));
// Legacy plans retain their original schema; adjusted plans use the handoff's
// sealed snapshot columns throughout native delivery, comparison and return.
export const bitwavePlanColumns=plan=>[...EXPORT_COLUMNS,...accountantColumns({source:plan.source})];
export const BITWAVE_DOCS=Object.freeze([
  {title:'Loaded data sources: create, schema and row batches',url:'https://docs.bitwave.io/docs/api-loaded-data-sources'},
  {title:'Retrieve rows: native table rows and pagination',url:'https://docs.bitwave.io/docs/get-datasource-rows'},
  {title:'API authentication',url:'https://docs.bitwave.io/reference/gettoken'},
  {title:'Bitwave original transaction exports',url:'https://docs.bitwave.io/docs/transactions-export-1'},
]);
const object=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
export const bitwaveHash=value=>createHash('sha256').update(value).digest('hex');
export function bitwaveCheck(ok,code,message,status=400){if(!ok)throw Object.assign(new Error(message),{code,status});}
export function bitwaveCanonical(value){
  if(value===null||typeof value==='string'||typeof value==='boolean')return JSON.stringify(value);
  if(typeof value==='number'){bitwaveCheck(Number.isFinite(value),'INVALID_BITWAVE_RECORD','A record has a non-finite number.');return JSON.stringify(value);}
  if(Array.isArray(value))return '['+value.map(bitwaveCanonical).join(',')+']';
  bitwaveCheck(object(value),'INVALID_BITWAVE_RECORD','Use JSON records.');
  return '{'+Object.keys(value).sort().map(key=>JSON.stringify(key)+':'+bitwaveCanonical(value[key])).join(',')+'}';
}
const sealed=body=>({...body,integrity:{sha256:bitwaveHash(bitwaveCanonical(body))}});
const copy=value=>JSON.parse(bitwaveCanonical(value));
const cell=value=>value===undefined||value===null?'':String(value);
export function bitwaveText(value,name,maximum=160,{empty=false}={}){
  bitwaveCheck(typeof value==='string'&&value.length<=maximum&&(empty||value.trim())&&!/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(value),'INVALID_BITWAVE_FIELD','Check '+name+'.');return value;
}
export function bitwaveId(value){bitwaveCheck(typeof value==='string'&&/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(value),'INVALID_BITWAVE_ID','Choose a retained Bitwave record.');return value;}
export function bitwaveTargetId(value,name='data source ID'){
  bitwaveCheck(typeof value==='string'&&/^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$/.test(value),'INVALID_BITWAVE_TARGET','Use the exact native '+name+'.');return value;
}

export function createBitwavePlan({handoff,revision=null,id=randomUUID(),name,actor,orgId,description='',batchSize=250,createdAt=new Date().toISOString()}={}){
  validateHandoff(handoff);if(revision)validateRevision(handoff,revision);
  bitwaveId(id);bitwaveText(name,'name');bitwaveText(actor,'operator',1000);bitwaveText(description,'description',2000,{empty:true});bitwaveTargetId(orgId,'organization ID');
  bitwaveCheck(Number.isInteger(batchSize)&&batchSize>=1&&batchSize<=250,'INVALID_BITWAVE_BATCH','Choose 1 to 250 rows per request.');
  bitwaveCheck(Number.isFinite(Date.parse(createdAt)),'INVALID_BITWAVE_TIME','Use a valid creation time.');
  const meta={handoffId:handoff.id,sourceRunId:handoff.source.runId,sourceReportSha256:handoff.source.reportSha256,
    sourcePeriodCloseId:handoff.source.periodClose?.id,sourcePeriodCloseSha256:handoff.source.periodClose?.sha256,sourcePeriodCloseRevision:handoff.source.periodClose?.revision,
    sourceAdjustmentsSha256:handoff.source.adjustments?.sha256};
  const columns=accountantColumns(handoff);
  const rows=inspectHandoff(handoff,revision).rows.map(item=>{
    const row={accountantExportRowId:bitwaveHash('stellar-forge.bitwave-row.v1\n'+id+'\n'+item.rowId),accountantExportId:id,
      accountantRevisionId:revision?.id??'',accountantRevisionSha256:revision?.integrity.sha256??''};
    for(const key of columns){
      row[key]=cell(Object.hasOwn(meta,key)?meta[key]:key==='rowId'?item.rowId:key==='sourceRowSha256'?item.sourceRowSha256:
        EDITABLE_COLUMNS.includes(key)?item[key]:Object.hasOwn(item.adjustments??{},key)?item.adjustments[key]:
        Object.hasOwn(item.label,key)?item.label[key]:item.original[key]);
    }
    return row;
  });
  bitwaveCheck(rows.length>0,'EMPTY_BITWAVE_SOURCE','Choose a handoff containing original merchant events.');
  const schemaColumns=[...EXPORT_COLUMNS,...columns].map(name=>({name,type:'stringType'}));
  const batches=[];
  for(let offset=0;offset<rows.length;offset+=batchSize){
    const index=batches.length+1,selected=rows.slice(offset,offset+batchSize),body={rows:selected};
    batches.push({index,offset,rowCount:selected.length,sha256:bitwaveHash(bitwaveJson(body)),file:'add-rows-'+String(index).padStart(4,'0')+'.json'});
  }
  return sealed({schema:BITWAVE_PLAN_SCHEMA,id,name,actor,orgId,description,createdAt,batchSize,
    handoffId:handoff.id,handoffSha256:handoff.integrity.sha256,accountantRevisionId:revision?.id??null,
    accountantRevisionSha256:revision?.integrity.sha256??null,source:copy(handoff.source),summary:copy(handoff.summary),
    rowCount:rows.length,idFieldName:'accountantExportRowId',schemaColumns,batches,rows,docs:copy(BITWAVE_DOCS)});
}
export function validateBitwavePlan(plan){
  bitwaveCheck(object(plan)&&plan.schema===BITWAVE_PLAN_SCHEMA&&object(plan.integrity),'INVALID_BITWAVE_PLAN','Choose a retained Bitwave plan.');
  const {integrity,...body}=plan;
  bitwaveCheck(bitwaveHash(bitwaveCanonical(body))===integrity.sha256,'BITWAVE_PLAN_CHANGED','The saved data-source plan changed.',409);
  bitwaveId(plan.id);bitwaveTargetId(plan.orgId,'organization ID');
  bitwaveCheck(Array.isArray(plan.rows)&&plan.rowCount===plan.rows.length&&plan.rows.length<=22000,'INVALID_BITWAVE_ROWS','The plan has an invalid source count.');
  const columns=bitwavePlanColumns(plan);
  bitwaveCheck(bitwaveCanonical(plan.schemaColumns)===bitwaveCanonical(columns.map(name=>({name,type:'stringType'})))&&
    plan.rows.every(row=>object(row)&&Object.keys(row).length===columns.length&&columns.every(name=>typeof row[name]==='string')),
    'BITWAVE_SCHEMA_CHANGED','Retain every exact string column from this original handoff schema.',409);
  return plan;
}
export const bitwaveJson=value=>Buffer.from(JSON.stringify(value,null,2)+'\n','utf8');
export function bitwaveCreateRequest(plan){validateBitwavePlan(plan);return {data:{name:plan.name,description:plan.description,type:'loaded',idFieldName:plan.idFieldName,schema:copy(plan.schemaColumns)}};}
export function bitwaveBatchRequest(plan,index){
  validateBitwavePlan(plan);const batch=plan.batches.find(item=>item.index===index);
  bitwaveCheck(batch,'BITWAVE_BATCH_NOT_FOUND','Choose a retained request batch.',404);
  return {rows:copy(plan.rows.slice(batch.offset,batch.offset+batch.rowCount))};
}

// Encode only when producing the accountant's spreadsheet format. The native
// Data Fusion JSON above carries the original plain value without display escapes.
const longNumeric=value=>/^(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+\-]?\d+)?$/.test(value)&&value.replace(/\D/g,'').length>15;
const escaped=value=>/^['\t\r\n]/.test(value)||/^\s*[=+\-@]/u.test(value)||longNumeric(value)?"'"+value:value;
const csvCell=value=>'"'+escaped(cell(value)).replace(/"/g,'""')+'"';
export function bitwaveRowsCsv(rows,columns=BITWAVE_COLUMNS){return Buffer.from([columns.map(csvCell).join(','),...rows.map(row=>columns.map(key=>csvCell(row[key])).join(','))].join('\r\n')+'\r\n','utf8');}

export function readBitwavePage(bytes){
  bitwaveCheck(Buffer.isBuffer(bytes)||bytes instanceof Uint8Array,'INVALID_BITWAVE_PAGE','Use the exact downloaded JSON file.');
  bitwaveCheck(bytes.length>0&&bytes.length<=64*1024*1024,'BITWAVE_PAGE_SIZE','A native page must be nonempty and at most 64 MiB.');
  let value;
  try{value=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}
  catch{bitwaveCheck(false,'INVALID_BITWAVE_JSON','The downloaded page must be valid UTF-8 JSON.');}
  bitwaveCheck(object(value)&&Array.isArray(value.items),'INVALID_BITWAVE_PAGE','Use the native table-rows response with its items array.');
  bitwaveCheck(value.items.length<=50000,'BITWAVE_ROW_LIMIT','A capture supports up to 50,000 source rows.');
  bitwaveCheck(value.items.every(object),'BITWAVE_NAMED_ROWS_REQUIRED','Use the native GET table-rows response with named row fields.');
  if(value.totalRows!==undefined)bitwaveCheck(Number.isSafeInteger(value.totalRows)&&value.totalRows>=0,'INVALID_BITWAVE_TOTAL','The native totalRows is not a nonnegative exact integer.');
  const token=value.nextPageToken??value.pageToken??value.bqPageToken??null;
  bitwaveCheck(token===null||typeof token==='string','INVALID_BITWAVE_CURSOR','The native page cursor must be text.');
  return {value,items:value.items,totalRows:value.totalRows??null,nextPageToken:token||null,truncated:value.truncated===true};
}

export function compareBitwavePages(plan,pageBytes){
  validateBitwavePlan(plan);
  const columns=accountantColumns({source:plan.source}),sourceColumns=bitwavePlanColumns(plan).filter(name=>!EDITABLE_COLUMNS.includes(name));
  bitwaveCheck(Array.isArray(pageBytes)&&pageBytes.length>0&&pageBytes.length<=500,'BITWAVE_PAGES_REQUIRED','Choose 1 to 500 ordered native response pages.');
  bitwaveCheck(pageBytes.reduce((n,bytes)=>n+bytes.length,0)<=64*1024*1024,'BITWAVE_CAPTURE_SIZE','A capture supports up to 64 MiB of native pages.');
  const pages=pageBytes.map(readBitwavePage),received=pages.flatMap(page=>page.items);
  bitwaveCheck(received.length<=50000,'BITWAVE_ROW_LIMIT','A capture supports up to 50,000 rows.');
  const issues=[],totals=new Set(pages.map(page=>page.totalRows).filter(total=>total!==null));
  if(totals.size>1)issues.push({code:'TOTAL_CHANGED',message:'The native total changed between pages. Capture the table again after the current changes finish.'});
  const total=totals.size===1?[...totals][0]:null;
  if(total!==null&&total!==received.length)issues.push({code:'INCOMPLETE_ROW_COUNT',message:'Received '+received.length+' rows; the native table reports '+total+'.'});
  if(pages.at(-1).nextPageToken)issues.push({code:'MORE_PAGES',message:'The last response has a next-page token. Retain the remaining native pages.'});
  if(pages.some(page=>page.truncated))issues.push({code:'TRUNCATED_NATIVE_PAGE',message:'A native response reports truncated data.'});
  if(total===null)issues.push({code:'NATIVE_TOTAL_UNAVAILABLE',message:'The native totalRows field is absent; capture completeness is not established.'});
  const byId=new Map(),unknown=[];
  const expected=new Map(plan.rows.map(row=>[row.accountantExportRowId,row]));
  for(let index=0;index<received.length;index++){
    const row=received[index],key=row.accountantExportRowId;
    if(typeof key!=='string'||!expected.has(key)){unknown.push({rowId:typeof row.rowId==='string'?row.rowId:null,status:'UNKNOWN',sourceRow:index+1,expected:null,received:row,changes:[]});continue;}
    const values=byId.get(key)??[];values.push({row,index});byId.set(key,values);
  }
  const items=[],matched=[];
  for(const original of plan.rows){
    const candidates=byId.get(original.accountantExportRowId)??[];
    if(!candidates.length){items.push({rowId:original.rowId,status:'MISSING',expected:original,received:null,changes:[]});continue;}
    if(candidates.length!==1){items.push({rowId:original.rowId,status:'DUPLICATE',expected:original,received:candidates.map(item=>item.row),changes:[],occurrences:candidates.length});continue;}
    const incoming=candidates[0].row,changes=[];
    for(const field of sourceColumns)if(typeof incoming[field]!=='string'||incoming[field]!==original[field])changes.push({field,expected:original[field],received:incoming[field]??null});
    for(const field of EDITABLE_COLUMNS)if(typeof incoming[field]!=='string')changes.push({field,expected:'text',received:incoming[field]??null});
    const status=changes.length?'CHANGED':'MATCHED';
    const item={rowId:original.rowId,status,expected:original,received:incoming,changes};items.push(item);
    if(status==='MATCHED')matched.push(Object.fromEntries(columns.map(key=>[key,incoming[key]])));
  }
  const count=status=>items.filter(item=>item.status===status).length;
  const summary={expectedRows:plan.rows.length,receivedRows:received.length,matchedRows:count('MATCHED'),changedRows:count('CHANGED'),missingRows:count('MISSING'),
    unknownRows:unknown.length,duplicateRows:count('DUPLICATE'),totalRows:total,pages:pages.length};
  const status=issues.length?'PARTIAL':'COMPLETE';
  const body={schema:BITWAVE_CAPTURE_SCHEMA,planId:plan.id,planSha256:plan.integrity.sha256,status,summary,issues,items:[...items,...unknown]};
  return {comparison:sealed(body),csvBytes:bitwaveRowsCsv(matched,columns)};
}

/** Merge remote edits against the exported revision and the current local return. */
export function prepareBitwaveReturn(plan,comparison,handoff,currentRevision=null){
  validateBitwavePlan(plan);validateHandoff(handoff);if(currentRevision)validateRevision(handoff,currentRevision);
  bitwaveCheck(handoff.id===plan.handoffId&&handoff.integrity.sha256===plan.handoffSha256&&comparison.planSha256===plan.integrity.sha256,
    'BITWAVE_RETURN_SOURCE_CHANGED','Choose the original handoff and comparison for this export.',409);
  const current=new Map(inspectHandoff(handoff,currentRevision).rows.map(row=>[row.rowId,row])),rows=[],editConflicts=[];
  for(const item of comparison.items){
    if(item.status!=='MATCHED')continue;
    const now=current.get(item.rowId),next={...item.received},fields=[];
    for(const field of EDITABLE_COLUMNS){
      const before=item.expected[field],incoming=item.received[field],local=cell(now[field]);
      if(incoming===before)next[field]=local;
      else if(local!==before&&local!==incoming)fields.push({field,exported:before,current:local,received:incoming});
    }
    if(fields.length)editConflicts.push({code:'ACCOUNTANT_EDIT_CONFLICT',rowId:item.rowId,fields,message:'The accountant and returned source changed the same field differently.'});
    else rows.push(next);
  }
  return {csvBytes:bitwaveRowsCsv(rows,accountantColumns(handoff)),editConflicts,matchedRows:rows.length};
}

// MIT. Reuse the accountant engine for a source-bound return to the original buyer.
import {createHandoff,validateHandoff,validateRevision,inspectHandoff} from './engine.mjs';
import {BUYER_RETURN_PACKET_SCHEMA,isBuyerHandoff,buyerCanonical,buyerHash,inspectBuyerSource} from './buyer-source.mjs';
const check=(ok,code,message,status=400)=>{if(!ok)throw Object.assign(new Error(message),{code,status});};
const clone=x=>JSON.parse(buyerCanonical(x));

export function createBuyerReturnPacket({handoff,revisions,buyerSourceBytes}={}){
  validateHandoff(handoff,{allowBuyer:true});
  check(isBuyerHandoff(handoff),'BUYER_HANDOFF_REQUIRED','Choose a buyer accountant handoff.');
  const inspected=inspectBuyerSource(buyerSourceBytes);
  const rebuilt=createHandoff({buyerSourceBytes,id:handoff.id,name:handoff.name,actor:handoff.actor,createdAt:handoff.createdAt,labels:handoff.labels});
  check(buyerCanonical(rebuilt)===buyerCanonical(handoff),'BUYER_RETURN_SOURCE_CHANGED','The accountant handoff does not bind to these exact original issued allocations.',409);
  check(Array.isArray(revisions)&&revisions.length>0&&revisions.length<=2000,'BUYER_RETURN_REQUIRED','Select a saved accountant return and its complete preceding history.');
  let previous=null;
  const ids=new Set();
  for(const revision of revisions){
    validateRevision(handoff,revision);
    check(!ids.has(revision.id)&&revision.parentRevisionId===(previous?.id??null)&&revision.parentRevisionSha256===(previous?.integrity.sha256??null),'BUYER_RETURN_CHAIN_CHANGED','Retain one complete original accountant return chain.',409);
    ids.add(revision.id);previous=revision;
  }
  const body={schema:BUYER_RETURN_PACKET_SCHEMA,source:{sha256:inspected.sha256,bytes:inspected.raw.length,...clone(inspected.source.buyer)},
    handoff:clone(handoff),revisions:clone(revisions),selectedRevisionId:previous.id};
  return {...body,integrity:{sha256:buyerHash(buyerCanonical(body))}};
}

/** Pure, bounded exact-file validation. It neither writes books nor edits expenses. */
export function inspectBuyerReturn({packetBytes,buyerSourceBytes}={}){
  const raw=Buffer.from(packetBytes);
  check(raw.length>0&&raw.length<=64*1024*1024,'BUYER_RETURN_SIZE','Choose a buyer accountant return JSON file up to 64 MiB.');
  let packet;try{packet=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw));}catch{check(false,'BUYER_RETURN_JSON','Choose a UTF-8 buyer accountant return JSON file.');}
  check(packet?.schema===BUYER_RETURN_PACKET_SCHEMA&&packet.integrity,'BUYER_RETURN_PACKET_REQUIRED','Download the original buyer-return.json file from the accountant handoff.');
  const rebuilt=createBuyerReturnPacket({handoff:packet.handoff,revisions:packet.revisions,buyerSourceBytes});
  check(buyerCanonical(packet)===buyerCanonical(rebuilt),'BUYER_RETURN_PACKET_CHANGED','The return packet or its original source identity changed.',409);
  const revision=packet.revisions.at(-1),view=inspectHandoff(packet.handoff,revision);
  return {schema:'stellar-forge.buyer-accountant-return-inspection.v1',packetSha256:buyerHash(raw),packetBytes:raw.length,
    source:clone(packet.source),handoffId:packet.handoff.id,handoffSha256:packet.handoff.integrity.sha256,
    selectedRevisionId:revision.id,selectedRevisionSha256:revision.integrity.sha256,
    revisions:packet.revisions.map(r=>({id:r.id,parentRevisionId:r.parentRevisionId,sha256:r.integrity.sha256,createdAt:r.createdAt,actor:r.actor,name:r.name,summary:r.summary})),
    rows:view.rows.map(row=>({sourceLineId:row.sourceLineId,rowId:row.rowId,kind:row.kind,sourceRowSha256:row.sourceRowSha256,
      original:clone(row.original),externalStatus:row.externalStatus,externalBookRef:row.externalBookRef,
      externalAccountCode:row.externalAccountCode,externalNote:row.externalNote,updatedBy:row.updatedBy,updatedAt:row.updatedAt,revisionId:row.revisionId})),
    summary:clone(revision.summary),issues:clone(revision.issues),missingRows:clone(revision.missingRows)};
}

// MIT. Typed source adapter for the original issued buyer expense period.
// No payment, journal, exchange-rate or merchant-report synthesis occurs here.
import {createHash,randomUUID} from 'node:crypto';

export const BUYER_SOURCE_SCHEMA='stellar-forge.buyer-accountant-source.v1';
export const BUYER_HANDOFF_SCHEMA='stellar-forge.buyer-accountant-handoff.v1';
export const BUYER_RETURN_SCHEMA='stellar-forge.buyer-accountant-return.v1';
export const BUYER_RETURN_PACKET_SCHEMA='stellar-forge.buyer-accountant-return-packet.v1';
const HEX=/^[0-9a-f]{64}$/;
const ID=/^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$/;
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const check=(ok,code,message,status=400)=>{if(!ok)throw Object.assign(new Error(message),{code,status});};
export const buyerHash=x=>createHash('sha256').update(x).digest('hex');
export function buyerCanonical(value){
  if(value===null||typeof value==='string'||typeof value==='boolean')return JSON.stringify(value);
  if(typeof value==='number'){check(Number.isFinite(value),'INVALID_BUYER_SOURCE','A retained source has an invalid number.');return JSON.stringify(value);}
  if(Array.isArray(value))return '['+value.map(buyerCanonical).join(',')+']';
  check(object(value),'INVALID_BUYER_SOURCE','Retain JSON-compatible source values.');
  return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+buyerCanonical(value[k])).join(',')+'}';
}
const copy=x=>JSON.parse(buyerCanonical(x));
const seal=x=>({...x,integrity:{sha256:buyerHash(buyerCanonical(x))}});
const text=(x,label,max=2000,empty=false)=>{
  check(typeof x==='string'&&x.length<=max&&(empty||x.trim())&&!/[\u0000-\u001f\u007f]/.test(x),'INVALID_BUYER_SOURCE','Retain '+label+' as exact text.');return x;
};
const ident=(x,label)=>{check(typeof x==='string'&&ID.test(x),'INVALID_BUYER_SOURCE','Retain the original '+label+'.');return x;};
const nativeAmount=(x,label)=>{check(typeof x==='string'&&/^(?:0|[1-9]\d{0,99})$/.test(x),'INVALID_BUYER_SOURCE','Retain '+label+' as an exact nonnegative native-unit string.');return BigInt(x);};
const date=x=>{check(typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&Number.isFinite(Date.parse(x+'T00:00:00Z'))&&new Date(x+'T00:00:00Z').toISOString().slice(0,10)===x,'INVALID_BUYER_SOURCE','Retain the original recognition date.');return x;};
const sourceLineId=(workspace,kind,row)=>buyerHash('stellar-forge.buyer-accountant-line.v1\n'+workspace+'\n'+kind+'\n'+row.coding_id+'\n'+row.line);
const rowId=(handoffId,sourceSha,lineId)=>buyerHash('stellar-forge.buyer-accountant-row.v1\n'+handoffId+'\n'+sourceSha+'\n'+lineId);

export const BUYER_FIELDS=Object.freeze([
  'allocationKind','sourceLineId','item_id','credit_id','source_id','source_name','source_capture','source_kind',
  'request_id','request_digest','recognition_date','network','asset','amount','settled_actual','native_return',
  'native_source_day','native_date_basis','receipt_ref','proof_sha256','packet_id','manifest_sha256',
  'adjustment_id','refund_id','source_reference','order_reference','original_transaction','transaction',
  'transfer_identity','observation_sha256','native_transfer_at','data_context',
  'center_id','center_code','center_name','project','account_code','memo','coding_id','line'
]);
export const BUYER_PROTECTED_COLUMNS=Object.freeze([
  'handoffId','sourceWorkspaceId','sourceCloseId','sourceCloseSequence','sourceContextSha256','sourceReportSha256',
  'rowId','sourceRowSha256',...BUYER_FIELDS,'assetLabel','unitLabel','accountCode','accountName'
]);
export const isBuyerHandoff=x=>x?.schema===BUYER_HANDOFF_SCHEMA;

function amountGroups(rows){
  const groups=new Map();
  for(const row of rows){const key=buyerCanonical([row.network,row.asset]),old=groups.get(key)??{network:row.network,asset:row.asset,amount:0n,lines:0};old.amount+=BigInt(row.amount);old.lines++;groups.set(key,old);}
  return [...groups.values()].map(row=>({...row,amount:row.amount.toString()})).sort((a,b)=>buyerCanonical([a.network,a.asset]).localeCompare(buyerCanonical([b.network,b.asset])));
}
function compareTotals(rows,totals,label){
  check(Array.isArray(totals),'INVALID_BUYER_SOURCE','Retain the original '+label+'.');
  const normalize=x=>x.map(row=>({network:row.network,asset:row.asset,amount:row.amount,lines:row.lines})).sort((a,b)=>buyerCanonical([a.network,a.asset]).localeCompare(buyerCanonical([b.network,b.asset])));
  check(buyerCanonical(amountGroups(rows))===buyerCanonical(normalize(totals)),'BUYER_TOTALS_CHANGED','The issued '+label+' do not match the retained allocation lines.',409);
}

/** Validate a closed, reviewed original period while retaining every source field. */
export function inspectBuyerSource(input){
  const raw=Buffer.from(input);
  check(raw.length>0&&raw.length<=64*1024*1024,'BUYER_SOURCE_SIZE','Choose an original buyer source JSON file up to 64 MiB.');
  let source;try{source=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw));}catch{check(false,'INVALID_BUYER_SOURCE','Choose original UTF-8 buyer source JSON.');}
  check(object(source)&&source.schema===BUYER_SOURCE_SCHEMA&&object(source.issued),'BUYER_SOURCE_REQUIRED','Export an issued accountant source from the original buyer expense workspace.');
  ident(source.workspaceId,'buyer workspace identity');
  const close=source.issued;
  check(close.schema==='stellar-forge.buyer-expense-period.v1'&&close.status==='CLOSED'&&close.ready===true&&close.unresolved===0&&object(close.period)&&close.period.state==='CLOSED'&&close.period.latest_close===close.id&&object(close.review)&&close.review.decision==='READY','BUYER_ISSUED_SOURCE_REQUIRED','Use a retained closed edition with its original completed review.');
  ident(close.id,'issued close identity');ident(close.period.id,'buyer period identity');
  check(Number.isSafeInteger(close.sequence)&&close.sequence>0&&HEX.test(close.context_sha256)&&typeof close.created_at==='string'&&Number.isFinite(Date.parse(close.created_at)),'INVALID_BUYER_SOURCE','Retain the issued sequence, time and source context.');
  const start=date(close.period.from_day),end=date(close.period.through_day);
  check(start<=end&&['operational','development'].includes(close.data_context??'operational'),'INVALID_BUYER_SOURCE','Retain the original period scope and data context.');
  check(Array.isArray(close.allocations)&&Array.isArray(close.credit_allocations??[])&&close.allocations.length+(close.credit_allocations??[]).length<=22000,'BUYER_ROW_LIMIT','Retain up to 22,000 issued expense and credit allocation lines.');
  const seen=new Set(),rows=[],economic=new Map();
  for(const [kind,lines]of [['EXPENSE',close.allocations],['CREDIT',close.credit_allocations??[]]]){
    for(const original of lines){
      check(object(original),'INVALID_BUYER_SOURCE','Retain the complete original allocation object.');
      for(const key of ['item_id','coding_id','source_id','source_capture','center_id'])ident(original[key],key);
      if(kind==='CREDIT')ident(original.credit_id,'credit identity');
      check(Number.isSafeInteger(original.line)&&original.line>0,'INVALID_BUYER_SOURCE','Retain the original positive allocation line number.');
