      result.status='DUPLICATE_ROW';conflictRows++;add(issue('DUPLICATE_ROW','Every repeated target is preserved from the previous revision; keep one returned row per original source.',record,{rowId:result.rowId,[key]:result[key],affectedRowIds:record.targets}));
    }else if(record.values&&record.row&&record.eventRow&&record.row.rowId===record.eventRow.rowId){
