        if(changed.length){result.status='PROTECTED_VALUE_CONFLICT';conflictRows++;add(issue('PROTECTED_VALUE_CONFLICT','Original identity, amounts, classifications and retained labels must match the exported source.',record,{rowId:row.rowId,...identity(row),fields:changed.map(field=>({field,expected:expected[field],received:record.values[field]}))}));}
        else {
          const previous=assignments.get(row.rowId);let edits;
          try{edits=editsFrom(record.values,previous);}catch(error){if(!(error instanceof AccountantError))throw error;result.status='INVALID_EDIT';conflictRows++;add(issue(error.code,error.message,record,{rowId:row.rowId,...identity(row)}));}
          if(edits){
            const changed=EDITABLE_COLUMNS.some(key=>edits[key]!==previous[key]);
            result.status=changed?'APPLIED':'UNCHANGED';
            if(changed){assignments.set(row.rowId,{...previous,...edits,updatedAt:createdAt,updatedBy:actor,revisionId:id});appliedRows++;}else unchangedRows++;
          }
