.filter-row, .filter-row label { max-width: 100%; }
.inset, .panel-heading, .document-scope, .purchase { overflow-wrap: anywhere; }
.table-wrap { max-width: 100%; }
#register table, #document-content table, #preview-content table { min-width: 640px; }
.pager { flex-wrap: wrap; }
@media (max-width: 1050px) {
  .workspace-grid { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 650px) {
  .form-grid, .key-values { grid-template-columns: minmax(0, 1fr); }
