  const value=state.buyerStartup;
  need(value.schema===BUYER_STARTUP_SCHEMA&&/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/.test(value.handoffId??'')&&SHA.test(value.sha256??'')&&
